# -*- coding: utf-8 -*-
# Gesundheitstipps der Naturheilpraxis. Ton: Lebensgewohnheiten und Tradition, keine Wirk- oder Heilversprechen (HWG).
T = []
def add(k, titel, kurz, text, zutaten=None, zubereitung=None):
    T.append(dict(k=k, titel=titel, kurz=kurz, text=text, zutaten=zutaten, zubereitung=zubereitung))

TEE="Tee der Jahreszeit"; AL="Alltagsgriff"; RZ="Hausmittel"; RU="Ruhe und Atem"; KN="Kneipp und Wasser"; BW="Bewegung"

add(TEE,"Ingwer-Zitronen-Tee","Wärmend und frisch: ein Klassiker für kalte Herbsttage.","Frischer Ingwer gibt dem Tee eine angenehme Schärfe, die viele an kühlen Tagen als wohltuend empfinden. Der Tee eignet sich als warmes Getränk zwischendurch. Wer empfindlich auf Schärfe reagiert, nimmt weniger Ingwer.",["3 cm frischer Ingwer","1 Bio-Zitrone","500 ml heißes Wasser","nach Geschmack Honig"],"Ingwer in dünne Scheiben schneiden, mit heißem Wasser übergießen und 10 Minuten ziehen lassen. Zitronensaft und nach Belieben Honig erst in die leicht abgekühlte Tasse geben.")
add(TEE,"Fencheltee am Abend","Ein ruhiger Abschluss des Tages.","Fenchel wird in der Volksheilkunde seit Langem als milder Abendtee geschätzt. Er schmeckt leicht süßlich und passt gut als feste Gewohnheit vor dem Schlafengehen, etwa nach dem Abendessen.",["1 TL Fenchelsamen","250 ml heißes Wasser"],"Die Samen kurz im Mörser leicht anquetschen, mit heißem Wasser übergießen, zugedeckt 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Salbeitee mit Zitrone","Herb-würzig und traditionell beliebt in der kühlen Jahreszeit.","Salbei hat einen kräftig-würzigen Geschmack und wird seit Jahrhunderten als Tee getrunken. Wegen des starken Aromas genügt eine kleine Menge. In Schwangerschaft und Stillzeit sowie bei Medikamenteneinnahme bitte vorher Rücksprache halten.",["4 bis 5 frische Salbeiblätter oder 1 TL getrockneter Salbei","250 ml heißes Wasser","etwas Zitronensaft"],"Salbei mit heißem Wasser übergießen, 5 bis 8 Minuten ziehen lassen, abseihen und mit Zitrone abschmecken.")
add(TEE,"Thymiantee","Aromatisch und warm, mit Honig besonders mild.","Thymian ist ein bekanntes Küchenkraut und liefert einen aromatischen, leicht herben Tee. Er passt gut zu nasskalten Tagen und lässt sich mit etwas Honig abrunden.",["1 TL getrockneter Thymian oder 2 frische Zweige","250 ml heißes Wasser","etwas Honig"],"Thymian mit heißem Wasser übergießen, 8 bis 10 Minuten zugedeckt ziehen lassen, abseihen und süßen.")
add(TEE,"Lindenblütentee","Ein sanfter, blumiger Wärmespender.","Lindenblütentee schmeckt mild und leicht süßlich. Er wird traditionell gern an kühlen Abenden getrunken, wenn man sich eine Auszeit mit einer warmen Tasse gönnen möchte.",["1 bis 2 TL Lindenblüten","250 ml heißes Wasser"],"Blüten mit heißem Wasser übergießen, 10 Minuten zugedeckt ziehen lassen und abseihen.")
add(TEE,"Hagebuttentee","Fruchtig-herb, ein kräftiger Herbstgeschmack.","Hagebutten sind die Früchte der Heckenrose und wachsen im Herbst an vielen Wegrändern. Der Tee hat eine fruchtig-säuerliche Note und färbt sich rötlich. Getrocknete Früchte gibt es im Handel.",["2 TL getrocknete Hagebutten","250 ml Wasser"],"Hagebutten leicht zerstoßen, mit kochendem Wasser übergießen und 10 bis 15 Minuten ziehen lassen, dann abseihen.")
add(TEE,"Kamillentee","Mild und vertraut, ein Tee für ruhige Minuten.","Kamille ist einer der bekanntesten Kräutertees. Er schmeckt mild und leicht blumig und begleitet viele Menschen durch ruhige Abende. Wer auf Korbblütler allergisch reagiert, sollte vorsichtig sein.",["1 EL Kamillenblüten","250 ml heißes Wasser"],"Blüten mit heißem Wasser übergießen, zugedeckt 5 bis 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Zimt-Apfel-Tee","Der Duft von Herbst und Weihnachtszeit.","Getrocknete Apfelstücke und eine Zimtstange ergeben einen Tee, der schon beim Aufgießen nach Herbst duftet. Zimt bitte in Maßen verwenden, Zimtstangen sind dabei meist die bessere Wahl als gemahlenes Pulver.",["1 Handvoll getrocknete Apfelstücke","1 Zimtstange","500 ml heißes Wasser"],"Äpfel und Zimtstange mit heißem Wasser übergießen, 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Holunderbeerensaft heiß","Warm, dunkel und fruchtig.","Holunderbeeren dürfen nicht roh gegessen werden, sondern müssen erhitzt werden. Als Saft schmeckt er heiß verdünnt wie ein fruchtiger Wintertee. Fertigen Saft gibt es im Reformhaus.",["100 ml Holunderbeersaft (gekauft oder selbst gekocht)","150 ml heißes Wasser","etwas Honig"],"Saft mit heißem Wasser mischen und nach Belieben mit Honig süßen.")
add(TEE,"Pfefferminztee zwischendurch","Frisch und klar, auch ohne Zucker lecker.","Pfefferminze bringt ein frisches, kühles Aroma in die Tasse. Der Tee passt zu jeder Tageszeit und lässt sich gut aus frischen Blättern vom Balkon aufgießen.",["1 Handvoll frische Pfefferminzblätter oder 1 TL getrocknete","250 ml heißes Wasser"],"Blätter mit heißem Wasser übergießen, 5 Minuten ziehen lassen und abseihen.")
add(TEE,"Brennnesseltee","Herb und grün, ein einfacher Kräutertee.","Brennnesseln gelten als typisches Wildkraut. Der Tee schmeckt herb-grün und wird in der Pflanzenheilkunde traditionell gern als Frühjahrs- oder Herbstkur genutzt. Wie bei jedem Kraut gilt: gute Qualität kaufen, in kleinen Mengen beginnen.",["1 bis 2 TL getrocknete Brennnesselblätter","250 ml heißes Wasser"],"Blätter mit heißem Wasser übergießen, 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Gewürztee mit Kardamom und Nelke","Ein duftender Wintertee für Genießer.","Kardamom, Nelke und Zimt ergeben eine Würzmischung, die an Chai erinnert. Sie schmeckt besonders mit etwas Milch oder Hafermilch. Wegen der Intensität genügt eine kleine Menge Gewürze.",["2 Kardamomkapseln","1 Nelke","1 Zimtstange","1 Scheibe Ingwer","250 ml Wasser"],"Gewürze leicht anquetschen, mit Wasser 5 Minuten leise kochen lassen, abseihen und nach Geschmack mit Milch verfeinern.")
add(TEE,"Lavendeltee zum Abschalten","Zart und blumig, mit nur wenigen Blüten.","Lavendel duftet intensiv. Für den Tee reicht deshalb eine kleine Menge, sonst schmeckt er seifig. Getrunken wird er traditionell zum Abendritual.",["1 TL Lavendelblüten (Lebensmittelqualität)","250 ml heißes Wasser"],"Blüten mit heißem Wasser übergießen, 5 Minuten ziehen lassen und abseihen.")

add(AL,"Das Glas Wasser am Morgen","Ein kleiner Anfang für den Tag.","Ein Glas Wasser nach dem Aufstehen ist eine einfache Gewohnheit. Viele nutzen sie, um bewusst in den Tag zu starten. Zimmerwarm ist für Empfindliche oft angenehmer als eiskalt.")
add(AL,"Warmes Fußbad am Abend","Wärme für Füße und Gedanken.","Ein warmes Fußbad ist ein bewährtes Hausmittel für kühle Abende. Der Wärmereiz ist für viele angenehm und lädt zum Abschalten ein. Das Wasser beginnt bei etwa 36 °C und darf auf 38 bis 40 °C ansteigen. Bei Durchblutungsstörungen oder Diabetes bitte vorher Rücksprache halten.",["Wanne mit Wasser","1 Handvoll Meersalz (optional)"],"15 bis 20 Minuten baden, danach abtrocknen und warme Socken anziehen.")
add(AL,"Kneipp: der kalte Armguss","Kurz, klar und belebend.","Ein kalter Armguss ist eine bekannte Kneipp-Anwendung. Dabei läuft kaltes Wasser kurz über die Arme. Viele erleben das als erfrischenden Start in den Tag. Bei Herz-Kreislauf-Beschwerden bitte zuvor ärztlichen Rat einholen.",None,"Kaltes Wasser vom Handgelenk aus langsam bis zur Schulter laufen lassen, etwa 20 bis 30 Sekunden, dann sanft abstreifen und warm anziehen.")
add(AL,"Spaziergang im Tageslicht","Draußen sein, auch bei grauem Wetter.","Im Herbst und Winter bekommen wir weniger Tageslicht. Ein halbstündiger Spaziergang am Vormittag bringt Bewegung und Licht, auch bei bewölktem Himmel. Der Himmel ist draußen auch dann heller als im Zimmer.")
add(AL,"Rhythmus statt Perfektion","Regelmäßig essen, schlafen, bewegen.","Der Körper mag Rhythmus. Feste Zeiten für Mahlzeiten und Schlaf geben vielen ein Gefühl von Halt. Das muss nicht streng sein, schon eine ungefähre Regelmäßigkeit ist eine gute Grundlage für einen geordneten Tag.")
add(AL,"Bewusst frühstücken","Zehn Minuten ohne Bildschirm.","Ein Frühstück ohne Handy und Nachrichten schafft einen ruhigen Beginn. Wer sich zehn Minuten Zeit nimmt, nimmt auch Hunger und Sättigung besser wahr.")
add(AL,"Die Wechseldusche","Warm und kalt im Wechsel, nach Kneipp.","Wechselduschen sind eine bekannte Kneipp-Anwendung. Dabei wird warmes und kaltes Wasser abwechselnd angewendet. Sie gelten als belebender Reiz. Bei Herz-Kreislauf-Erkrankungen bitte nur nach Rücksprache.",None,"Erst warm duschen, dann kurz kalt von den Füßen aufwärts abbrausen, abtrocknen und warm anziehen. Mit wenigen Sekunden Kälte beginnen.")
add(AL,"Stoßlüften statt Dauerkipp","Frische Luft in der Heizperiode.","Im Winter ist die Raumluft oft trocken. Mehrmals täglich ein paar Minuten die Fenster ganz öffnen bringt frische Luft in die Räume, ohne sie auszukühlen. Das Schlafzimmer darf ruhig kühler sein.")
add(AL,"Bewegung in kleinen Portionen","Fünf Minuten zählen schon.","Wer viel sitzt, kann stündlich kurz aufstehen, sich strecken, ein Glas Wasser holen und ein paar Schritte gehen. Solche kleinen Pausen summieren sich und lockern Schultern und Rücken.")
add(AL,"Barfuß auf dem Boden","Füße spüren lassen.","Barfuß zu Hause zu gehen, ist eine einfache Möglichkeit, die Füße zu beanspruchen und die Haut wahrzunehmen. Bei Kälte tragen wir natürlich Hausschuhe oder warme Socken.")
add(AL,"Der Tag mit einem Dank","Eine Minute am Abend.","Am Abend kurz überlegen, was gut gelaufen ist, ist ein einfaches Ritual. Viele empfinden das als gelassen machend und schließen den Tag damit ruhiger ab.")

add(RU,"Atmen: vier ein, sechs aus","Eine einfache Übung für zwischendurch.","Eine bekannte Atemübung ist die längere Ausatmung: durch die Nase vier Sekunden einatmen, durch den Mund sechs Sekunden ausatmen. Fünf Wiederholungen reichen. Viele empfinden das als beruhigend. Bei Schwindel die Übung abbrechen.")
add(RU,"Eine Minute Stille","Nichts tun, nur da sein.","Eine Minute still zu sitzen, ohne Handy und ohne Aufgabe, ist eine kleine Pause für den Kopf. Man kann dabei auf den Atem achten oder auf die Geräusche im Raum.")
add(RU,"Der Abendspaziergang","Den Tag draußen ausklingen lassen.","Ein kurzer Spaziergang nach dem Abendessen gehört in vielen Kulturen zum Tagesablauf. Er bringt Bewegung, frische Luft und einen Abstand zum Alltag.")
add(RU,"Handy aus, Licht gedämpft","Eine halbe Stunde vor dem Schlafen.","Wer vor dem Schlafen Bildschirme meidet und das Licht dämpft, gibt dem Abend einen ruhigeren Ablauf. Statt Nachrichten kann ein Buch oder eine Tasse Tee den Tag beschließen.")
add(RU,"Schlafzimmer kühl und dunkel","Gute Bedingungen für die Nacht.","Viele schlafen in einem kühlen, dunklen und leisen Zimmer besser. Etwa 16 bis 18 °C gelten als angenehm. Ein Lüften vor dem Schlafengehen gehört dazu.")
add(RU,"Dehnen am Morgen","Fünf Minuten für den Rücken.","Nach dem Aufstehen ein paar Minuten die Arme nach oben strecken, die Schultern kreisen und den Rücken sanft dehnen. Das kann sich lockernd anfühlen und ist ein einfacher Start in den Tag.")

add(RZ,"Zwiebelsirup nach Großmutters Art","Ein altes Hausrezept.","Zwiebelsirup ist ein traditionelles Hausmittel aus zwei Zutaten. Er wird in vielen Familien seit Generationen zubereitet. Für Menschen mit empfindlichem Magen ist er vielleicht nicht das Richtige.",["1 große Zwiebel","3 EL Honig oder Zucker"],"Zwiebel würfeln, mit Honig vermengen, einige Stunden zugedeckt stehen lassen und den entstandenen Saft abseihen.")
add(TEE,"Goldene Milch","Warm, cremig und gewürzt.","Goldene Milch ist ein Getränk aus Milch oder Pflanzenmilch mit Kurkuma und Ingwer. Sie ist beliebt als warmer Abendbegleiter. Kurkuma färbt stark, bitte nicht auf helle Textilien kleckern.",["250 ml Milch oder Hafermilch","1 TL Kurkuma","1 Scheibe Ingwer","1 Prise Pfeffer","etwas Honig"],"Alles erwärmen, nicht kochen, 5 Minuten ziehen lassen, abseihen und mit Honig abschmecken.")

add(KN,"Wassertreten","Kühles Wasser, kurze Dauer, warme Füße danach.","Wassertreten gehört zu den bekanntesten Kneipp-Anwendungen: Man steht in kniehohem kaltem Wasser und hebt abwechselnd die Beine wie ein Storch. Viele erleben das als erfrischend. Wichtig ist, dass die Füße vorher warm sind und danach wieder gut gewärmt werden. Bei Blasenreizung, Durchblutungsstörungen oder Herz-Kreislauf-Beschwerden bitte vorher Rücksprache halten.",None,"Badewanne oder Eimer mit kaltem Wasser bis zu den Knien füllen, 30 bis 60 Sekunden storchenartig gehen, Wasser abstreifen, warme Socken anziehen und sich bewegen.")
add(KN,"Der Knieguss","Ein kurzer Wasserstrahl, ein belebender Reiz.","Der Knieguss ist ein klassischer Kneipp-Guss. Kaltes Wasser läuft von den Füßen aufwärts bis zum Knie. Viele beschreiben ihn als erfrischenden Beginn oder Abschluss des Tages. Mit wenigen Sekunden beginnen und nur mit warmen Füßen anwenden.",None,"Wasserstrahl ohne Druck am rechten Fuß von außen beginnen, an der Außenseite bis zum Knie hinaufführen und an der Innenseite zurück. Dann links wiederholen, Wasser abstreifen und warm anziehen.")
add(BW,"Schultern lösen","Eine Minute für Nacken und Schultern.","Wer viel sitzt, kennt verspannte Schultern. Mehrmals am Tag die Schultern langsam nach hinten kreisen, die Arme locker hängen lassen und dabei ruhig atmen. Das kann sich wohltuend anfühlen und kostet kaum Zeit.")
add(BW,"Der Igelball unter dem Fuß","Die Fußsohle spüren und rollen.","Mit einem kleinen Igel- oder Tennisball unter dem Fuß lässt sich die Fußsohle sanft massieren. Man rollt den Ball langsam von der Ferse bis zum Ballen. Viele finden das angenehm, besonders nach langem Stehen. Bei Schmerzen die Übung abbrechen.")
add(BW,"Zehn Schritte mit Aufmerksamkeit","Langsam gehen und den Boden spüren.","Eine einfache Übung im Alltag: zehn Schritte ganz langsam gehen und auf den Kontakt der Füße mit dem Boden achten. Sie lässt sich im Flur oder im Garten üben und macht den Kopf frei.")
add(RZ,"Orangenschalen als Raumduft","Ein natürlicher Duft für kalte Tage.","Frische Orangenschalen mit ein paar Nelken auf der warmen Heizung oder in einer Schale verbreiten einen angenehmen Duft. Der Duft von Zitrusfrüchten wird von vielen als frisch und heiter empfunden. Auf Bio-Qualität achten.",["Schalen von 2 Bio-Orangen","3 bis 4 Nelken","1 Zimtstange (optional)"],"Schalen mit Nelken und Zimt in eine Schale legen und auf einen warmen Platz stellen.")
add(RU,"Das Summen am Abend","Eine Minute summen, ruhig ausatmen.","Beim Ausatmen einen tiefen, gleichmäßigen Summton hervorbringen: Man spürt die Schwingung im Gesicht und im Brustkorb. Viele empfinden das als beruhigend. Drei bis fünf Atemzüge genügen. Bei Schwindel die Übung beenden.")
add(RU,"Herbst: Zeit des Loslassens","Ein Gedanke aus der Traditionellen Chinesischen Medizin.","In der Traditionellen Chinesischen Medizin gilt der Herbst als Zeit des Elements Metall. Es steht sinnbildlich für Klarheit und Loslassen, so wie Bäume die Blätter abwerfen. Ein Anlass, den Herbst bewusst zu nutzen: Altes sortieren, Überflüssiges abgeben, früh nach Hause gehen und die Abende ruhiger gestalten.")

# ---- Erweiterung auf 100 Tipps ----
TC="Gedanke aus der TCM"; FR="Früher selbstverständlich"
add(TC,"Die Mitte warm halten","Warme Mahlzeiten, vor allem morgens und abends.","In der Traditionellen Chinesischen Medizin (TCM) gilt die Verdauung als eine Art Kochtopf der Mitte, der gern warm gehalten wird. Daher werden warme Speisen und Getränke traditionell bevorzugt, vor allem am Morgen. Ein warmer Haferbrei oder ein warmer Tee statt kaltem Müsli ist eine einfache Umsetzung.")
add(TC,"Warm trinken, in kleinen Schlucken","Statt kalter Getränke lieber zimmerwarm oder warm.","In der TCM wird eiskaltes Trinken traditionell zurückhaltend gesehen. Warmes oder zimmerwarmes Wasser in kleinen Schlucken über den Tag verteilt ist eine einfache Gewohnheit, die viele als angenehm empfinden.")
add(TC,"Frühling: früh aufstehen","Der Jahreszeit folgen: mehr Licht, mehr Bewegung.","Nach der TCM gehört der Frühling dem Element Holz. Es steht sinnbildlich für Aufbruch und Wachstum. Traditionell rät man dazu, früher aufzustehen, sich morgens zu bewegen und den Garten oder den Wald zu nutzen. Ein guter Moment, Pläne anzufangen und den Körper nach dem Winter zu lockern.")
add(TC,"Sommer: Freude und Weite","Draußen sein, Kontakt, Lachen.","Der Sommer gilt in der TCM als Zeit des Elements Feuer, sinnbildlich für Lebensfreude, Begegnung und Herz. Man nutzt die langen Tage, geht lange auf, trifft Menschen, lacht und genießt. Nur die Mittagshitze meidet man und gönnt sich dann eine Ruhepause im Schatten.")
add(TC,"Spätsommer: die Zeit der Mitte","Regelmäßig essen, langsam und in Ruhe.","Der Spätsommer entspricht in der TCM dem Element Erde, sinnbildlich für Mitte, Ernährung und Fürsorge. Passend sind feste Essenszeiten, eine Mahlzeit ohne Hast und süßliche, reife Früchte der Saison.")
add(TC,"Winter: Ruhe und Rückzug","Früher ins Bett und Kräfte sammeln.","Der Winter gehört in der TCM dem Element Wasser, sinnbildlich für Tiefe, Ruhe und Reserven. Traditionell geht man im Winter früher schlafen, steht später auf und plant weniger. Wärmende Getränke, warme Kleidung und stille Abende passen in diese Zeit.")
add(TC,"Den Nacken schützen","Ein Schal, der an kalten Tagen guttut.","In der TCM gilt der Nacken als Stelle, an der Wind und Kälte leicht eindringen. Ein Schal oder hochgestellter Kragen an windigen Tagen ist ein alter Brauch, den man leicht umsetzen kann und der sich angenehm anfühlt.")
add(TC,"Den unteren Rücken wärmen","Die Nierengegend schützen, besonders im Winter.","In der TCM gilt die Gegend um den unteren Rücken als Sitz der Nierenenergie, die man traditionell warm hält. Ein längeres Oberteil, das den Rücken bedeckt, oder ein Wärmekissen auf dem Rücken an kalten Abenden sind einfache Umsetzungen.")
add(TC,"Die fünf Geschmacksrichtungen","Süß, sauer, bitter, scharf und salzig im Wechsel.","Die TCM kennt fünf Geschmacksrichtungen, die jeweils einem Element zugeordnet sind. Eine abwechslungsreiche Ernährung mit allen fünf, ohne Übertreibung, entspricht dem Grundgedanken. Wer im Alltag einseitig isst, kann einmal darauf achten, welche Geschmacksrichtung fehlt.")
add(TC,"Nur zu etwa 70 Prozent satt essen","Ein alter Grundsatz: aufhören, bevor man voll ist.","In der asiatischen Tradition gilt der Rat, nur bis etwa sieben Zehntel satt zu essen. Man isst langsam und hört auf, bevor sich ein Völlegefühl einstellt. Das ist eine Gewohnheit, die sich Schritt für Schritt üben lässt.")
add(TC,"Die Ohren massieren","Eine kleine Übung für zwischendurch.","Die Ohrmuschel wird in der asiatischen Tradition als Landkarte des Körpers gesehen. Eine einfache Selbstmassage: Die Ohren zwischen Daumen und Zeigefinger von oben nach unten sanft streichen und leicht reiben. Viele empfinden das als wohltuend und wärmend.")
add(TC,"Arme und Beine abklopfen","Klopfen in der Tradition des Qigong.","Im Qigong werden Arme und Beine mit der lockeren Faust oder der flachen Hand von oben nach unten abgeklopft. Das wird traditionell als Weg beschrieben, den Körper zu wecken. Man klopft sanft, nie schmerzhaft.")
add(TC,"Schütteln wie im Qigong","Eine Minute locker schütteln.","Eine einfache Qigong-Übung: Man steht hüftbreit, lässt die Knie locker und schüttelt sanft den ganzen Körper aus den Beinen heraus. Das entspannt Schultern und Arme. Eine Minute genügt. Bei Schwindel oder Gelenkproblemen langsam vorgehen.")
add(TC,"Die Augen mit den Händen wärmen","Eine kleine Pause für müde Augen.","Die Handflächen aneinander reiben, bis sie warm sind, und dann locker auf die geschlossenen Augen legen. Diese Übung kennt man als Palmieren. Viele empfinden sie als wohltuend nach langem Bildschirmtag.")
add(TC,"Mittags kurz ruhen","Die Mittagspause als Teil des Tages.","In vielen Kulturen gehört ein kurzer Ruhemoment zur Mittagszeit. Zehn bis zwanzig Minuten Hinlegen oder Sitzen mit geschlossenen Augen geben dem Nachmittag oft einen neuen Schwung. Länger zu schlafen kann den Nachtschlaf stören.")
add(TC,"Yin und Yang im Tag","Aktive Zeiten und ruhige Zeiten im Wechsel.","Yin und Yang beschreiben Gegensätze, die einander ergänzen: aktiv und ruhig, warm und kühl, Tag und Nacht. Im Alltag heißt das, auf einen aktiven Abschnitt bewusst einen ruhigen folgen zu lassen und umgekehrt.")

add(FR,"Mit dem Licht leben","Aufstehen mit der Sonne, früh zur Ruhe.","Früher richtete sich der Tag nach dem Tageslicht. Wer im Herbst und Winter früher zur Ruhe kommt und das Morgenlicht nutzt, folgt diesem alten Rhythmus. Ein Spaziergang am Vormittag ist ein einfacher Anfang.")
add(FR,"Nach dem Essen hundert Schritte","Ein alter Rat nach der Mahlzeit.","Der Spruch ›Nach dem Essen sollst du ruhn oder tausend Schritte tun‹ ist alt. Ein kurzer Spaziergang nach dem Essen gehört in vielen Familien zum Alltag und tut dem Rhythmus des Tages gut.")
add(FR,"Kopf und Füße warm","Eine alte Faustregel für kalte Tage.","Früher sagte man: Kopf kühl, Füße warm. Wärmende Wollsocken und eine Mütze bei Kälte sind eine einfache Umsetzung. Kalte Füße lassen sich oft durch ein warmes Fußbad oder Hausschuhe angenehmer machen.")
add(FR,"Das Fenster öffnen","Frische Luft im Wohnraum, jeden Tag.","Früher gehörte das Stoßlüften selbstverständlich zum Tag. Ein paar Minuten weit geöffnetes Fenster morgens und abends tauschen die Luft und machen den Kopf klar.")
add(FR,"Kräuter sammeln und trocknen","Ein Vorrat aus dem Garten.","Im Sommer und Herbst wurden Kräuter in Bündeln an einem luftigen, schattigen Platz getrocknet. Pfefferminze, Melisse, Thymian und Lavendel eignen sich gut. So hat man im Winter einen eigenen Teevorrat.",None,"Kräuter an trockenen Tagen am späten Vormittag pflücken, nicht waschen, locker bündeln, kopfüber an einem schattigen Ort aufhängen und nach ein bis zwei Wochen in Gläser füllen.")
add(FR,"Mit Salzwasser gurgeln","Ein altes Hausmittel für Morgen und Abend.","Gurgeln mit lauwarmem Salzwasser ist ein Hausmittel, das viele aus der Familie kennen. Es ist günstig, schnell gemacht und lässt sich in den Alltag einbauen.",["1/2 TL Salz","1 Glas lauwarmes Wasser"],"Salz im Wasser auflösen, einige Sekunden gurgeln und ausspucken. Nicht schlucken.")
add(FR,"Das Kirschkernkissen","Wärme aus dem Ofen oder der Mikrowelle.","Ein Kissen mit Kirschkernen speichert Wärme und ist ein beliebtes Hausmittel für kalte Abende. Man legt es sich auf Bauch, Rücken oder Füße. Beim Erwärmen auf die Temperatur achten, damit man sich nicht verbrennt.",None,"Kissen im Backofen bei etwa 100 °C zehn Minuten oder in der Mikrowelle kurz erwärmen, Temperatur mit der Hand prüfen und anschließend auflegen.")
add(FR,"Wollsocken im Bett","Warme Füße zum Einschlafen.","Warme Füße sind für viele die Voraussetzung, gut einzuschlafen. Wollsocken oder eine Wärmflasche am Fußende sind ein alter, einfacher Brauch.")
add(FR,"Vor Mitternacht schlafen","Die Stunden vor Mitternacht zählen.","Ein alter Spruch sagt: Eine Stunde Schlaf vor Mitternacht ist mehr wert als zwei danach. Wer es einrichten kann, geht im Herbst und Winter früher ins Bett und lässt den Tag früher ausklingen.")
add(FR,"Der Sonntag als Ruhetag","Ein Tag ohne Pflichten.","Der Ruhetag hat eine lange Tradition. Ein Tag in der Woche mit weniger Terminen, ohne Pflichten und mit einem Spaziergang, einem gemeinsamen Essen oder einem Buch tut vielen gut.")
add(FR,"Gründlich kauen","Jeden Bissen bewusst genießen.","Früher hieß es: Gut gekaut ist halb verdaut. Wer langsam isst, schmeckt mehr und spürt früher, wann er satt ist. Ein einfacher Versuch: Jeden Bissen fünfzehn- bis zwanzigmal kauen.")
add(FR,"Handarbeit als Ruheinsel","Stricken, Flechten, Nähen.","Handarbeiten wie Stricken, Häkeln oder Sticken gehörten früher selbstverständlich zu den Abenden. Der gleichmäßige Rhythmus kann sich beruhigend anfühlen, und am Ende hat man etwas Greifbares in der Hand.")
add(FR,"Bei Regen spazieren gehen","Wetter gehört dazu.","Ein Spaziergang im Regen mit guter Kleidung ist ein Erlebnis. Die Luft ist frisch, die Düfte intensiver. Wer sich vorher warm anzieht und danach warm trinkt, hat Freude daran.")
add(FR,"Ein Tagebuch am Abend","Drei Sätze genügen.","Früher schrieb man Tagebuch. Heute geht das mit Zettel und Stift am Abend: drei Sätze, was war schön, was war schwer, was kommt morgen. Das sortiert die Gedanken und kann den Abend ruhiger machen.")
add(FR,"Wasser abstreifen statt abtrocknen","Eine Kneipp-Gewohnheit.","Nach kalten Güssen streift man das Wasser mit den Händen ab, statt sich kräftig abzurubbeln. Anschließend zieht man sich warm an und bewegt sich, bis die Haut wieder warm ist.")

add(TEE,"Melissentee","Zitronig, mild und für den Sommer geeignet.","Zitronenmelisse hat ein frisches, leicht zitroniges Aroma. Der Tee schmeckt warm und kalt. Melisse wächst in vielen Gärten, frische Blätter ergeben das feinste Aroma.",["1 Handvoll frische Melissenblätter oder 2 TL getrocknete","250 ml heißes Wasser"],"Blätter mit heißem Wasser übergießen, 5 bis 8 Minuten ziehen lassen und abseihen.")
add(TEE,"Zitronenverbene","Duftend und fein, ein Sommertee.","Zitronenverbene ist eine duftende Pflanze, die auf Balkonen wächst. Ihre Blätter geben einen feinen zitronigen Tee, der warm und kalt schmeckt.",["5 bis 6 frische Blätter","250 ml heißes Wasser"],"Blätter mit heißem Wasser übergießen, 5 Minuten ziehen lassen und abseihen.")
add(TEE,"Minz-Eistee","Erfrischend in der warmen Jahreszeit.","Frische Minze und Zitrone ergeben einen Eistee ohne Zucker. Er lässt sich gut vorbereiten und im Kühlschrank aufbewahren.",["1 Handvoll Minzblätter","1 Bio-Zitrone","1 Liter Wasser"],"Minze mit heißem Wasser übergießen, 10 Minuten ziehen lassen, abseihen, abkühlen lassen und mit Zitronenscheiben kalt stellen.")
add(TEE,"Holunderblütentee","Duftend, nach Sommer schmeckend.","Holunderblüten blühen im Frühsommer und werden traditionell als Tee oder Sirup verwendet. Der Duft erinnert an Sommertage. Die Blüten nur an sauberen Standorten pflücken.",["2 Holunderblütendolden oder 1 EL getrocknete Blüten","250 ml heißes Wasser"],"Blüten mit heißem Wasser übergießen, 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Löwenzahnblätter im Frühling","Bittere Frühlingskräuter.","Junge Löwenzahnblätter schmecken herb und werden seit Langem im Frühling gesammelt. Der Tee ist bitter und passt zu Menschen, die den herben Geschmack mögen. Nur ungespritzte Wiesen nutzen.",["1 Handvoll junge Löwenzahnblätter","250 ml heißes Wasser"],"Blätter fein hacken, mit heißem Wasser übergießen, 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Ringelblumentee","Sonnig gelb und mild im Geschmack.","Ringelblumenblüten geben dem Tee eine goldgelbe Farbe und einen milden Geschmack. Die Pflanze wächst problemlos im Garten. Wer auf Korbblütler allergisch ist, sollte vorsichtig sein.",["1 EL Ringelblumenblüten","250 ml heißes Wasser"],"Blüten mit heißem Wasser übergießen, 10 Minuten ziehen lassen und abseihen.")
add(TEE,"Malventee","Tiefblau und mild.","Malvenblüten färben den Tee tiefblau und werden mit Zitronensaft rosa. Das Farbspiel macht Freude, der Geschmack ist mild und leicht schleimig.",["1 TL Malvenblüten","250 ml heißes Wasser","einige Tropfen Zitronensaft"],"Blüten mit heißem Wasser übergießen, 10 Minuten ziehen lassen, abseihen und mit Zitrone die Farbe wechseln lassen.")
add(TEE,"Rosenblütentee","Duftend und festlich.","Getrocknete Rosenblüten aus Bio-Qualität geben dem Tee ein zartes Aroma. Er passt zu ruhigen Nachmittagen und festlichen Anlässen.",["1 EL getrocknete Rosenblüten","250 ml heißes Wasser"],"Blüten mit heißem Wasser übergießen, 5 bis 8 Minuten ziehen lassen und abseihen.")
add(TEE,"Basilikumtee","Würzig und ungewöhnlich.","Frisches Basilikum kennt man aus der Küche. Als Tee schmeckt es mild-würzig, mit einer leichten Süße. Besonders aromatisch ist das indische Basilikum, auch Tulsi genannt.",["1 Handvoll Basilikumblätter","250 ml heißes Wasser"],"Blätter leicht quetschen, mit heißem Wasser übergießen, 5 Minuten ziehen lassen und abseihen.")
add(TEE,"Gurkenwasser","Kühl und leicht für heiße Tage.","Gurkenscheiben im Wasser geben einen milden, frischen Geschmack. Ein schöner Ersatz für gesüßte Getränke an heißen Tagen.",["1/2 Bio-Gurke","1 Liter Wasser","einige Minzblätter"],"Gurke in Scheiben schneiden, mit Wasser und Minze mehrere Stunden kühl stellen.")
add(TEE,"Kräuter-Kaltauszug","Sanft und ohne Hitze.","Beim Kaltauszug ziehen Kräuter über Nacht im kalten Wasser. Der Geschmack ist besonders mild. Gut geeignet sind Pfefferminze, Melisse und Zitronenverbene.",["1 Handvoll frische Kräuter","1 Liter kaltes Wasser"],"Kräuter in eine Karaffe geben, mit kaltem Wasser auffüllen und über Nacht im Kühlschrank ziehen lassen.")
add(TEE,"Sonnentee im Glas","Wärme der Sonne nutzen.","Ein Glasgefäß mit Wasser und Kräutern an einem sonnigen Tag auf die Fensterbank stellen. Die Sonne wärmt das Wasser langsam, der Tee wird mild.",["1 Handvoll Kräuter oder Teebeutel","1 Liter Wasser"],"Zutaten in ein Glasgefäß geben, einige Stunden an einen sonnigen Platz stellen, abseihen und gekühlt trinken.")

add(RU,"Wechselatmung","Eine alte Yogaübung für den Abend.","Bei der Wechselatmung atmet man abwechselnd durch das linke und das rechte Nasenloch. Man schließt mit dem Daumen das rechte, atmet links ein, schließt links mit dem Ringfinger und atmet rechts aus, und wechselt dann. Fünf Runden genügen. Bei Schwindel abbrechen.")
add(RU,"Bauchatmung","Die Hand auf dem Bauch spüren.","Eine Hand auf den Bauch legen und so atmen, dass sie sich beim Einatmen hebt und beim Ausatmen senkt. Fünf bis zehn ruhige Atemzüge reichen. Viele empfinden das als entspannend.")
add(RU,"Eine Minute Fernblick","Augen ausruhen am Bildschirm.","Wer lange auf einen Bildschirm blickt, kann alle zwanzig Minuten für zwanzig Sekunden in die Ferne schauen, zum Beispiel aus dem Fenster. Das ist ein einfacher Weg, die Augen zwischendurch zu entlasten.")
add(RU,"Waldbaden","Im Wald einfach da sein.","Waldbaden kommt aus Japan und heißt, ohne Ziel im Wald zu gehen und die Umgebung wahrzunehmen. Man geht langsam, bleibt stehen, atmet tief und schaut. Eine Stunde reicht.")
add(RU,"Digitale Pause am Abend","Eine Stunde ohne Bildschirm.","Eine Stunde vor dem Schlafen das Handy beiseitelegen und stattdessen ein Buch lesen, Musik hören oder miteinander sprechen. Viele empfinden den Abend dann als ruhiger.")
add(RU,"Der Baum, eine Standübung","Fest stehen und tief atmen.","Eine bekannte Übung aus dem Qigong: Man steht hüftbreit, die Knie sind leicht gebeugt, die Arme bilden einen Kreis vor der Brust. Zwei bis fünf Minuten ruhig atmen und den Boden spüren. Bei Schwindel beenden.")
add(RU,"Dankbare Minute","Drei gute Dinge des Tages.","Am Abend drei Dinge nennen, für die man dankbar ist. Das lässt sich still oder laut tun, auch zu zweit am Esstisch. Der Blick geht dann zuerst auf das Gelungene.")

add(KN,"Das kalte Armbad","Kurz und erfrischend.","Das Armbad ist eine bekannte Kneipp-Anwendung: Man taucht die Arme bis zur Mitte der Oberarme für etwa 30 Sekunden in kaltes Wasser. Viele erleben es als belebend, zum Beispiel an heißen Tagen. Bei Durchblutungsstörungen vorher Rücksprache halten.",None,"Waschbecken mit kaltem Wasser füllen, Arme einige Sekunden eintauchen, Wasser abstreifen und Arme bewegen, bis sie warm sind.")
add(KN,"Taulaufen","Barfuß durch das nasse Gras.","Barfuß durch das taufeuchte Gras zu gehen, ist eine alte Kneipp-Übung. Man geht nur kurz, einige Minuten, und wärmt danach die Füße. Ein schönes Erlebnis an Sommermorgen.")
add(KN,"Das Wechselfußbad","Warm und kalt im Wechsel.","Beim Wechselfußbad stehen die Füße erst drei Minuten in warmem, dann zehn bis dreißig Sekunden in kaltem Wasser. Das wiederholt man zwei- bis dreimal. Viele empfinden es als wohltuend an müden Tagen. Bei Durchblutungsstörungen oder Diabetes vorher Rücksprache halten.")
add(KN,"Der Schenkelguss","Ein Guss für die Beine.","Beim Schenkelguss wird kaltes Wasser von den Füßen aufwärts bis zur Hüfte geführt. Es ist ein klassischer Kneipp-Guss, der eine gewisse Erfahrung mit dem Knieguss voraussetzt. Nur mit warmen Füßen und mit wenigen Sekunden beginnen.")

add(BW,"Handgelenke und Finger kreisen","Zwischendurch lockern.","Wer viel schreibt oder tippt, kann zwischendurch Handgelenke und Finger langsam kreisen. Dazu die Hände ausschütteln. Eine halbe Minute genügt und fühlt sich oft wohltuend an.")
add(BW,"Kiefer lockern","Zähne auseinander, Zunge locker.","Viele pressen unbewusst die Zähne zusammen. Eine einfache Übung: Mund leicht öffnen, den Kiefer locker hängen lassen und mit den Fingerspitzen die Kaumuskeln vor den Ohren sanft kreisen. Das kann sich entspannend anfühlen.")
add(BW,"Treppe statt Aufzug","Alltagsbewegung nutzen.","Im Alltag lassen sich viele kleine Wege zu Fuß zurücklegen. Treppen steigen, ein Telefonat im Stehen oder im Gehen führen und ein Stück vor dem Ziel aussteigen bringen zusätzliche Bewegung, ohne dass man dafür Zeit einplanen muss.")
add(BW,"Auf einem Bein stehen","Eine Gleichgewichtsübung.","Beim Zähneputzen eine Minute auf einem Bein stehen und dann wechseln. Das schult das Gleichgewicht und lässt sich leicht in den Alltag einbauen. Zur Sicherheit eine Hand an der Wand lassen.")
add(BW,"Sonnengruß am Morgen","Fließende Bewegung zum Start.","Der Sonnengruß ist eine bekannte Abfolge aus dem Yoga, die den ganzen Körper dehnt und streckt. Zwei Durchgänge am Morgen sind ein schöner Anfang. Wer Beschwerden hat, wählt eine einfachere Variante.")

add(RZ,"Lavendelsäckchen","Ein Duft für den Schrank und das Kopfkissen.","Ein kleines Säckchen mit getrocknetem Lavendel verbreitet einen dezenten Duft im Kleiderschrank oder neben dem Kopfkissen. Der Duft ist vielen vertraut und erinnert an Gärten im Sommer.",["2 EL getrocknete Lavendelblüten","kleines Stoffsäckchen"],"Blüten in das Säckchen füllen, zubinden und in den Schrank oder neben das Kissen legen.")
